    ChangeMessageVisibilityBatchRequestEntry.add_member(:visibility_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: NullableInteger, location_name: 'VisibilityTimeout', traits: {"smithy.api#documentation" => "<p>The new value (in seconds) for the message's visibility timeout.</p>"}))
