    RemovePermissionRequest.add_member(:label, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Label', traits: {"smithy.api#documentation" => "<p>The identification of the permission to remove. This is the label added using the\n                    <code>\n               <a>AddPermission</a>\n            </code> action.</p>", "smithy.api#required" => {}}))
